// ============================================
// HELPER FUNCTIONS
// ============================================

/**
 * Lấy danh sách sản phẩm hiển thị trên slider trang chủ
 */
function getSliderProducts() {
    // Ưu tiên showInSlider, rồi theo thứ tự chung (featured → bestseller → mới); không lặp cùng template
    const seen = new Set();
    return getProductsSorted()
        .filter(p => p.type === 'invitation')
        .sort((a, b) => (b.showInSlider ? 1 : 0) - (a.showInSlider ? 1 : 0))
        .filter(p => { const k = p.templateOf || p.id; if (seen.has(k)) return false; seen.add(k); return true; })
        .slice(0, 6);
}

/**
 * Lấy product theo id
 */
function getProductById(id) {
    return PRODUCTS.find(p => p.id === Number(id));
}

/**
 * Lấy product theo slug
 */
function getProductBySlug(slug) {
    return PRODUCTS.find(p => p.slug === slug);
}

/**
 * Lấy danh sách products đã sort theo priority
 */
function getProductsSorted() {
    const typeOrder = { 'invitation': 0, 'website': 1, 'google-sheet': 2 };
    const statusRank = { 'bestseller': 0, 'trending': 1, 'hot': 2 };
    const rank = (p) => statusRank[p.status] ?? 9;
    const time = (p) => Date.parse(p.updatedAt || '2000-01-01') || 0;

    return [...PRODUCTS].filter(p => p.isPublic !== false).sort((a, b) => {
        const aType = typeOrder[a.type] ?? 3, bType = typeOrder[b.type] ?? 3;
        if (aType !== bType) return aType - bType;
        // priority chỉ còn là "bucket": 0 = bình thường, 100 = legacy đẩy cuối
        if ((a.priority || 0) !== (b.priority || 0)) return (a.priority || 0) - (b.priority || 0);
        if (!!a.featured !== !!b.featured) return a.featured ? -1 : 1;
        if (rank(a) !== rank(b)) return rank(a) - rank(b);
        if (time(a) !== time(b)) return time(b) - time(a);
        return b.id - a.id;
    });
}

/** NEW = cập nhật trong 30 ngày gần đây (tự tính, không dùng status:'new') */
function isNewProduct(p) {
    const t = Date.parse(p.updatedAt || '');
    return !!t && (Date.now() - t) < 30 * 86400000;
}

// Nhãn phong cách (thiệp cưới) và sự kiện (thiệp khác) — dùng cho chip lọc + sub-label card
const STYLE_LABELS = {
    traditional: 'Truyền thống', modern: 'Hiện đại', minimalist: 'Tối giản',
    luxury: 'Sang trọng', floral: 'Hoa lá', vintage: 'Vintage',
};
const EVENT_LABELS = {
    wedding: 'Đám cưới', 'dam-ngo': 'Dạm ngõ', 'an-hoi': 'Ăn hỏi',
    birthday: 'Sinh nhật', 'thoi-noi': 'Thôi nôi & Đầy tháng', anniversary: 'Kỷ niệm',
    reunion: 'Họp lớp', 'gio-to': 'Giỗ tổ', confession: 'Tỏ tình', graduation: 'Tốt nghiệp',
    holiday: 'Lễ hội', other: 'Khác',
};

/**
 * Lọc products theo category, type, và search keyword
 */
function filterProducts({ category = 'all', type = 'all', search = '', style = 'all', event = 'all' } = {}) {
    return getProductsSorted().filter(p => {
        const matchCategory = category === 'all' || p.category === category;
        const matchType = type === 'all' || p.type === type;
        if (style !== 'all' && p.style !== style) return false;
        if (event !== 'all' && p.event !== event) return false;
        const matchSearch = !search ||
            p.name.toLowerCase().includes(search.toLowerCase()) ||
            p.description.toLowerCase().includes(search.toLowerCase()) ||
            p.tags.some(t => t.toLowerCase().includes(search.toLowerCase()));
        return matchCategory && matchType && matchSearch;
    });
}

/**
 * Phân trang
 */
function paginateProducts(products, page = 1, perPage = 9) {
    const total = products.length;
    const totalPages = Math.ceil(total / perPage);
    const start = (page - 1) * perPage;
    const items = products.slice(start, start + perPage);
    return { items, total, totalPages, currentPage: page };
}

/**
 * Lấy related products (cùng category, loại trừ product hiện tại)
 */
function getRelatedProducts(productId, limit = 4) {
    const product = getProductById(productId);
    if (!product) return [];
    return PRODUCTS
        .filter(p => p.id !== product.id && p.category === product.category && p.isPublic !== false)
        .sort((a, b) => a.priority - b.priority)
        .slice(0, limit);
}

/**
 * Submit form đến Google Sheets API
 */
async function submitToGoogleSheet(formData) {
    if (!API_CONFIG.GOOGLE_SHEET_API) {
        console.warn('Google Sheet API URL chưa được cấu hình.');
        return { success: false, message: 'API chưa được cấu hình.' };
    }

    try {
        const response = await fetch(API_CONFIG.GOOGLE_SHEET_API, {
            method: 'POST',
            mode: 'no-cors',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ...formData, sheet_name: 'sale' }),
        });
        return { success: true, message: 'Gửi thành công!' };
    } catch (error) {
        console.error('Submit error:', error);
        return { success: false, message: 'Có lỗi xảy ra, vui lòng thử lại.' };
    }
}
